351	    fn proof_body(state: &AppState, key: &TestKey, did: &str, timestamp: i64, fill: u8) -> Value {
352	        let nonce = URL_SAFE_NO_PAD.encode([fill; NONCE_BYTES]);
353	        let envelope = crypto::encode_sovereign_session_envelope(
354	            &state.config.resolve_server_did(),
