2	//
3	// The shared "which keys may sign a sovereign proof for this account" lookup, behind the two
4	// passwordless auth surfaces (`POST /v1/sessions/sovereign`, `POST /oauth/authorize/approve`).
5	// Signature verification is already method-agnostic (`crypto::verify_did_key_signature` over a
6	// `did:key:` URI, P-256 and secp256k1), so the authority lookup is the only place a DID method
7	// matters. It lives here rather than in either route because routes may not import one another.
8	//
9	// Both methods resolve their authority **live** from the authoritative source, never from the
10	// `did_documents` cache — for did:plc because `rotationKeys` is authoritative only in the latest
11	// non-nullified audit-log operation, and for did:web because that cache is writable by
12	// `POST /v1/did-web/document`.
13	
14	use common::ApiError;
15	use serde_json::Value;
16	
17	use crate::app::AppState;
18	
19	use super::plc::fetch_current_plc_state;
20	use super::resolution::resolve_web_did_document;
21	
22	/// The set of `did:key:` URIs currently authorized to sign a sovereign proof for an account,
23	/// plus a short description of the authority state they were read from (for the success log).
24	pub struct AuthoritySet {
25	    keys: Vec<String>,
26	    pub source: String,
27	}
28	
29	impl AuthoritySet {
30	    pub fn authorizes(&self, signing_key: &str) -> bool {
31	        self.keys.iter().any(|key| key == signing_key)
32	    }
33	}
34	
35	/// A failed authority lookup, split by who the caller should blame.
36	pub enum AuthorityError {
37	    /// The DID method, document, or policy denies any authority. The caller collapses this into
38	    /// its own opaque rejection — it must never become a distinguishable response.
39	    Unauthorized(&'static str),
40	    /// The authoritative source could not be consulted. Propagated as-is so an upstream outage
41	    /// still fails closed with its own status (a plc.directory 503 stays a 502, not a 401).
42	    Lookup(ApiError),
43	}
44	
45	fn is_plc_did(value: &str) -> bool {
46	    let Some(suffix) = value.strip_prefix("did:plc:") else {
47	        return false;
48	    };
49	    suffix.len() == 24
50	        && suffix
51	            .bytes()
52	            .all(|byte| byte.is_ascii_lowercase() || (b'2'..=b'7').contains(&byte))
53	}
54	
55	/// Resolve the account's current signing authority from its DID method's authoritative source.
56	pub async fn authorized_signing_keys(
57	    state: &AppState,
58	    did: &str,
59	) -> Result<AuthoritySet, AuthorityError> {
60	    if is_plc_did(did) {
61	        plc_authority(state, did).await
62	    } else if did.starts_with("did:web:") {
63	        web_authority(state, did).await
64	    } else {
65	        Err(AuthorityError::Unauthorized("unsupported_did_method"))
66	    }
67	}
68	
69	/// did:plc — every key in the DID's current `rotationKeys`. A Custos-held rotation key qualifies
70	/// under exactly the same PLC semantics as any other, granting Custos no power over an account it
71	/// already hosts: rewriting the rotation set requires an existing rotation key, and plc.directory
72	/// is external to this server.
73	async fn plc_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
74	    let plc = fetch_current_plc_state(&state.http_client, &state.config.plc_directory_url, did)
75	        .await
76	        .map_err(AuthorityError::Lookup)?;
77	    Ok(AuthoritySet {
78	        keys: plc.rotation_keys,
79	        source: format!("plc:{}", plc.cid),
80	    })
81	}
82	
83	/// did:web — exactly the document's `{did}#device` verification method, and nothing else.
84	///
85	/// Not "any verificationMethod": `#atproto`'s private key is Custos-held, so a broader set would
86	/// let this server sign its own sovereign envelope for an account it hosts. `#device` alone also
87	/// keeps one rule across both did:web paths — `create_did.rs` already enforces `#device`
88	/// specifically when promoting a new did:web.
89	///
90	/// Gated on self-hosted only. `POST /v1/did-web/document` lets an account rewrite its served
91	/// document under mere session auth, so for a Custos-hosted did:web a stolen session could install
92	/// an attacker `#device` key and bootstrap sovereign sessions — a privilege escalation with no key
93	/// compromise. That route already refuses unless hosting is enabled, so
94	/// `did_web_hosting_enabled_at IS NULL` **is** the condition "no session-authed rewrite is
95	/// possible", with no gap in either direction. Making `#device` immutable across such an edit
96	/// would let this gate be dropped later without redesigning anything.
97	async fn web_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
98	    // Cheap DB gate before the outbound fetch.
99	    if crate::db::dids::did_web_hosting_enabled(&state.db, did)
100	        .await
101	        .map_err(AuthorityError::Lookup)?
102	    {
103	        return Err(AuthorityError::Unauthorized("did_web_hosting_enabled"));
104	    }
105	
106	    let document = resolve_web_did_document(state, did)
107	        .await
108	        .map_err(AuthorityError::Lookup)?;
109	    let device_key = device_verification_key(&document, did)?;
110	    Ok(AuthoritySet {
111	        keys: vec![device_key],
112	        source: "did:web#device".to_string(),
113	    })
114	}
115	
116	/// Extract the document's `#device` key as a `did:key:` URI, matching `create_did.rs`'s predicate
117	/// (`type == "Multikey"`, `controller == did`, exact `{did}#device` id). The difference in shape:
118	/// `create_did.rs` *verifies* a known key by comparing `publicKeyMultibase`, whereas this
119	/// *discovers* it, so it extracts that field instead — rendered as `did:key:{multibase}`, since the
120	/// verification method carries bare multibase while a PLC rotation set stores `did:key:` URIs.
121	///
122	/// More than one `#device`-shaped entry is malformed (duplicate `id` values already violate DID
123	/// Core) and fails closed rather than picking one by array order.
124	fn device_verification_key(document: &Value, did: &str) -> Result<String, AuthorityError> {
125	    let expected_id = format!("{did}#device");
126	    let methods = document
127	        .get("verificationMethod")
128	        .and_then(Value::as_array)
129	        .ok_or(AuthorityError::Unauthorized("no_verification_methods"))?;
130	    let mut matches = methods.iter().filter(|method| {
131	        method.get("id").and_then(Value::as_str) == Some(&expected_id)
132	            && method.get("type").and_then(Value::as_str) == Some("Multikey")
133	            && method.get("controller").and_then(Value::as_str) == Some(did)
134	    });
135	    let Some(method) = matches.next() else {
136	        return Err(AuthorityError::Unauthorized(
137	            "no_device_verification_method",
138	        ));
139	    };
140	    if matches.next().is_some() {
141	        return Err(AuthorityError::Unauthorized(
142	            "duplicate_device_verification_method",
143	        ));
144	    }
145	    let multibase = method
146	        .get("publicKeyMultibase")
147	        .and_then(Value::as_str)
148	        .ok_or(AuthorityError::Unauthorized("device_key_not_multibase"))?;
149	    Ok(format!("did:key:{multibase}"))
150	}
151	
152	#[cfg(test)]
153	mod tests {
154	    use super::*;
155	    use serde_json::json;
156	
157	    const WEB_DID: &str = "did:web:example.com";
158	
159	    fn document(methods: Value) -> Value {
160	        json!({ "id": WEB_DID, "verificationMethod": methods })
161	    }
162	
163	    fn device_method(multibase: &str) -> Value {
164	        json!({
165	            "id": format!("{WEB_DID}#device"),
166	            "type": "Multikey",
167	            "controller": WEB_DID,
168	            "publicKeyMultibase": multibase
169	        })
170	    }
171	
172	    fn key(document: &Value) -> Result<String, AuthorityError> {
173	        device_verification_key(document, WEB_DID)
174	    }
175	
176	    fn reason(result: Result<String, AuthorityError>) -> &'static str {
177	        match result {
178	            Err(AuthorityError::Unauthorized(reason)) => reason,
179	            _ => panic!("expected an Unauthorized rejection"),
180	        }
181	    }
182	
183	    #[test]
184	    fn device_method_is_rendered_as_a_did_key_uri() {
185	        let doc = document(json!([device_method("zDevice")]));
186	        assert_eq!(key(&doc).ok().as_deref(), Some("did:key:zDevice"));
187	    }
188	
189	    #[test]
190	    fn the_custos_held_atproto_key_is_never_authority() {
191	        let doc = document(json!([{
192	            "id": format!("{WEB_DID}#atproto"),
193	            "type": "Multikey",
194	            "controller": WEB_DID,
195	            "publicKeyMultibase": "zRepo"
196	        }]));
197	        assert_eq!(reason(key(&doc)), "no_device_verification_method");
198	    }
199	
200	    #[test]
201	    fn a_duplicate_device_entry_fails_closed_instead_of_picking_by_order() {
202	        let doc = document(json!([device_method("zFirst"), device_method("zSecond")]));
203	        assert_eq!(reason(key(&doc)), "duplicate_device_verification_method");
204	    }
205	
206	    #[test]
207	    fn a_device_entry_failing_any_predicate_field_is_not_authority() {
208	        for method in [
209	            json!({"id": format!("{WEB_DID}#device"), "type": "JsonWebKey2020", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
210	            json!({"id": format!("{WEB_DID}#device"), "type": "Multikey", "controller": "did:web:attacker.example", "publicKeyMultibase": "zDevice"}),
211	            json!({"id": "did:web:other.example#device", "type": "Multikey", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
212	        ] {
213	            assert_eq!(
214	                reason(key(&document(json!([method])))),
215	                "no_device_verification_method"
216	            );
217	        }
218	    }
219	
220	    #[test]
221	    fn a_device_entry_without_a_multibase_key_is_rejected() {
222	        let doc = document(json!([{
223	            "id": format!("{WEB_DID}#device"),
224	            "type": "Multikey",
225	            "controller": WEB_DID
226	        }]));
227	        assert_eq!(reason(key(&doc)), "device_key_not_multibase");
228	    }
229	
230	    #[test]
231	    fn a_document_without_verification_methods_is_rejected() {
232	        assert_eq!(
233	            reason(device_verification_key(&json!({"id": WEB_DID}), WEB_DID)),
234	            "no_verification_methods"
235	        );
236	    }
237	
238	    #[test]
239	    fn plc_did_syntax_is_enforced_exactly() {
240	        assert!(is_plc_did("did:plc:aaaaaaaaaaaaaaaaaaaaaaaa"));
241	        assert!(!is_plc_did("did:plc:tooshort"));
242	        assert!(!is_plc_did("did:plc:AAAAAAAAAAAAAAAAAAAAAAAA"));
243	        assert!(!is_plc_did("did:plc:aaaaaaaaaaaaaaaaaaaaaaa1"));
244	        assert!(!is_plc_did(WEB_DID));
245	    }
246	}
