431	/// Compute the `RemovalOutcome` after a successful `retire_and_wipe`.
432	fn removal_outcome(tombstone_cid: Option<String>) -> Result<RemovalOutcome, RemovalError> {
433	    Ok(RemovalOutcome {
434	        tombstone_cid,
435	        was_last_identity: no_identities_remain()?,
436	    })
437	}
