686	    /// Conversely, the wipe runs exactly once after a successful submit.
687	    #[tokio::test]
688	    async fn wipe_runs_after_successful_submit() {
689	        let wiped = Arc::new(AtomicBool::new(false));
690	        let w = wiped.clone();
691	        let result = submit_then_wipe(async { Ok(()) }, move || {
692	            w.store(true, Ordering::SeqCst);
693	            Ok(())
694	        })
695	        .await;
696	
697	        assert!(result.is_ok());
698	        assert!(
699	            wiped.load(Ordering::SeqCst),
700	            "local wipe must run after a successful tombstone submit"
701	        );
702	    }
703	
704	    /// A 401 from deleteAccount (wrong password) and a 400 INVALID_TOKEN (bad/expired
705	    /// code) both surface as `InvalidToken`, so the UI re-prompts identically.
706	    #[test]
707	    fn delete_account_credential_failures_map_to_invalid_token() {
708	        assert!(matches!(
709	            map_delete_account_error(PdsClientError::Unauthorized {
710	                error: Some("InvalidToken".to_string()),
711	                message: "bad password".to_string(),
712	            }),
713	            RemovalError::InvalidToken
714	        ));
715	        assert!(matches!(
716	            map_delete_account_error(PdsClientError::XrpcError {
717	                status: 400,
718	                error: Some("InvalidToken".to_string()),
719	                message: "expired".to_string(),
720	            }),
721	            RemovalError::InvalidToken
722	        ));
723	        // A non-credential XRPC failure is distinct.
724	        assert!(matches!(
725	            map_delete_account_error(PdsClientError::XrpcError {
726	                status: 500,
727	                error: Some("InternalError".to_string()),
728	                message: "oops".to_string(),
729	            }),
730	            RemovalError::AccountDeleteFailed { .. }
731	        ));
732	    }
733	
734	    // ── Pending-removal marker lifecycle ──────────────────────────────────────
735	    //
736	    // The marker is the post-delete recovery hook: `deleteAccount` succeeding but the
737	    // tombstone/wipe not finishing must leave a durable, resumable trace.
738	
739	    #[test]
740	    fn pending_removal_marker_round_trip() {
