795	        assert_eq!(
796	            store.list_identities().unwrap(),
797	            vec!["did:plc:gone".to_string()]
798	        );
799	        // A stale marker from an interrupted prior attempt must be cleared too.
800	        mark_removal_pending("did:plc:gone").unwrap();
801	
802	        let was_last = forget_identity_locally("did:plc:gone".to_string()).unwrap();
803	
804	        assert!(
805	            was_last,
