28	pub enum SovereignLoginError {
29	    #[error("identity not found")]
30	    IdentityNotFound,
31	    #[error("the identity's hosting server does not support Custos sovereign login")]
32	    UnsupportedHost,
33	    #[error("the hosting server rejected the device-key proof")]
34	    AuthorizationFailed,
35	    #[error("the hosting server rate limited the login")]
36	    RateLimited { retry_after: Option<String> },
37	    #[error("transport failure: {message}")]
38	    TransportFailure { message: String },
39	    #[error("keychain failure: {message}")]
40	    KeychainFailure { message: String },
41	    #[error("signing failure: {message}")]
42	    SigningFailed { message: String },
43	    #[error("the discovered DID document did not match the selected identity")]
44	    DidMismatch,
45	    #[error("invalid hosting server identity")]
46	    ServerMismatch,
