1	// pattern: Imperative Shell
2	//
3	// The wallet-confirmed half of OAuth consent. Three public routes plus a wallet preview, all keyed
4	// off the single-use `pending_oauth_authorizations` request the consent page
5	// (`oauth_authorize::get_authorization`) created:
6	//
7	//   GET  /oauth/authorize/consent-request  — wallet preview: client/origin/scope for a user_code
8	//   GET  /oauth/authorize/status           — browser poll (slow_down-throttled), returns {status}
9	//   POST /oauth/authorize/approve          — device-key-signed approve/deny of a request
10	//   POST /oauth/authorize/complete         — browser exchanges an approved request for the code
11	//
12	// Approval is proven with a canonical device-key envelope in the `sovereign_session` mold
13	// (`crypto::encode_oauth_consent_envelope`), verified against the account's **authoritative**
14	// current signing authority (`identity::authority` — a did:plc rotation set, or a self-hosted
15	// did:web's `#device` key) — never the cached DID doc. The envelope binds `request_id`, `client_id`, the
16	// decision, and a hash of the granted scope set, so an approval cannot be replayed onto a different
17	// request, flipped from a denial, or widened. Replay of the same envelope onto its own request is
18	// stopped by the single-use guarded status transition (the request_id binding + single-use row
19	// together subsume a nonce store). This module never imports another route handler.
20	
21	use std::time::{Duration, Instant};
22	
23	use axum::{
24	    extract::{Form, Query, State},
25	    http::StatusCode,
26	    response::{IntoResponse, Json, Response},
27	};
28	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
29	use common::{ApiError, ErrorCode, SOVEREIGN_TIMESTAMP_WINDOW_SECS};
30	use serde::{Deserialize, Serialize};
31	
32	use crate::app::AppState;
33	use crate::auth::token::generate_token;
34	use crate::db::oauth::store_authorization_code;
35	use crate::db::pending_oauth_authorizations::{
36	    approve_pending_authorization, complete_pending_authorization, deny_pending_authorization,
37	    get_pending_by_request_id, get_pending_by_user_code, insert_oauth_consent_audit_event,
38	    OAuthConsentAuditEventType,
39	};
40	use crate::identity::authority::{authorized_signing_keys, AuthorityError};
41	use crate::routes::oauth_templates::{build_code_redirect, error_page};
42	
43	const SIGNATURE_BYTES: usize = 64;
44	const NONCE_BYTES: usize = 32;
45	/// Minimum spacing between accepted status polls for one request; a faster poll gets the
46	/// `slow_down` 429 the page's JS backs off on (the `claim_polling` discipline).
47	const STATUS_POLL_MIN_INTERVAL: Duration = Duration::from_secs(2);
48	
49	// ── Shared helpers ──────────────────────────────────────────────────────────────
50	
51	fn decode_canonical_base64url(value: &str, expected_len: usize) -> Option<Vec<u8>> {
52	    let decoded = URL_SAFE_NO_PAD.decode(value).ok()?;
53	    (decoded.len() == expected_len && URL_SAFE_NO_PAD.encode(&decoded) == value).then_some(decoded)
54	}
55	
56	/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
57	/// response so the caller can't probe request state beyond "pending or not".
58	fn not_approvable() -> ApiError {
59	    ApiError::new(
60	        ErrorCode::NotFound,
61	        "authorization request not found or expired",
62	    )
63	}
64	
65	/// Signature / authority / binding failures share one message so the surface reveals nothing about
66	/// which check failed.
67	fn approval_rejected() -> ApiError {
68	    ApiError::new(
69	        ErrorCode::AuthenticationRequired,
70	        "consent approval rejected",
71	    )
72	}
73	
74	/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
75	/// always granted (never optional), and every other token is kept only if it was part of the
76	/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
77	/// tampered/injected token that was never requested cannot add scope — only narrow it.
78	fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
79	    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
80	    requested_scope
81	        .split_whitespace()
82	        .filter(|t| *t == "atproto" || wallet.contains(t))
83	        .collect::<Vec<_>>()
84	        .join(" ")
85	}
86	
87	// ── Preview ─────────────────────────────────────────────────────────────────────
88	
89	#[derive(Deserialize)]
90	pub struct ConsentRequestQuery {
91	    /// Typed path: the human-entered `user_code`. Exactly one of `user_code` / `request_id`.
92	    user_code: Option<String>,
93	    /// Handoff path: the `request_id` carried by the "Open in Obsign" link.
94	    request_id: Option<String>,
95	}
96	
97	#[derive(Serialize)]
98	#[serde(rename_all = "camelCase")]
99	pub struct ConsentRequestPreview {
100	    request_id: String,
101	    client_id: String,
102	    client_name: Option<String>,
103	    redirect_uri: String,
104	    origin: Option<String>,
105	    ip: Option<String>,
106	    requested_scope: Vec<String>,
107	    login_hint: Option<String>,
108	}
109	
110	/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
111	/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
112	/// a guessed code reveals nothing.
113	pub async fn get_consent_request(
114	    State(state): State<AppState>,
115	    Query(query): Query<ConsentRequestQuery>,
116	) -> Result<Json<ConsentRequestPreview>, ApiError> {
117	    let pending = match (&query.user_code, &query.request_id) {
118	        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
119	        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
120	        _ => {
121	            return Err(ApiError::new(
122	                ErrorCode::InvalidRequest,
123	                "exactly one of userCode or requestId is required",
124	            ))
125	        }
126	    };
127	    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
128	    let Some(p) = pending else {
129	        return Err(not_approvable());
130	    };
131	    Ok(Json(ConsentRequestPreview {
132	        request_id: p.request_id,
133	        client_id: p.client_id,
134	        client_name: p.client_name,
135	        redirect_uri: p.redirect_uri,
136	        origin: p.origin,
137	        ip: p.ip,
138	        requested_scope: p
139	            .requested_scope
140	            .split_whitespace()
141	            .map(str::to_string)
142	            .collect(),
143	        login_hint: p.login_hint,
144	    }))
145	}
146	
147	// ── Status poll ─────────────────────────────────────────────────────────────────
148	
149	#[derive(Deserialize)]
150	pub struct StatusQuery {
151	    request_id: String,
152	}
153	
154	#[derive(Serialize)]
155	struct StatusResponse {
156	    status: &'static str,
157	}
158	
159	/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
160	/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
161	/// a derived `expired` for a lapsed or reclaimed request so the page stops.
162	pub async fn get_authorization_status(
163	    State(state): State<AppState>,
164	    Query(query): Query<StatusQuery>,
165	) -> Response {
166	    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
167	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
168	    {
169	        let key = format!("consent:{}", query.request_id);
170	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
171	        if let Some(last) = tracker.get(&key) {
172	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
173	                return (
174	                    StatusCode::TOO_MANY_REQUESTS,
175	                    Json(StatusResponse {
176	                        status: "slow_down",
177	                    }),
178	                )
179	                    .into_response();
180	            }
181	        }
182	        tracker.insert(key, Instant::now());
183	    }
184	
185	    let pending = match get_pending_by_request_id(&state.db, &query.request_id).await {
186	        Ok(p) => p,
187	        Err(e) => return e.into_response(),
188	    };
189	    let status = match pending {
190	        // Absent (never created or reclaimed) reads as expired so the page stops polling.
191	        None => "expired",
192	        Some(p) if p.status == "pending" && p.is_expired => "expired",
193	        Some(p) => match p.status.as_str() {
194	            "pending" => "pending",
195	            "approved" => "approved",
196	            "denied" => "denied",
197	            "completed" => "completed",
198	            _ => "expired",
199	        },
200	    };
201	    Json(StatusResponse { status }).into_response()
202	}
203	
204	// ── Approve / deny ──────────────────────────────────────────────────────────────
205	
206	#[derive(Deserialize)]
207	#[serde(rename_all = "camelCase", deny_unknown_fields)]
208	pub struct ApprovalRequest {
209	    did: String,
210	    signing_key: String,
211	    request_id: String,
212	    /// `"approve"` or `"deny"` — bound into the signed envelope so a captured denial cannot be
213	    /// replayed as an approval.
214	    decision: String,
215	    /// Space-joined granted-scope string the wallet chose (empty for a denial). Signed verbatim.
216	    #[serde(default)]
217	    granted_scope: String,
218	    timestamp: i64,
219	    nonce: String,
220	    signature: String,
221	}
222	
223	#[derive(Serialize)]
224	#[serde(rename_all = "camelCase")]
225	pub struct ApprovalResponse {
226	    status: &'static str,
227	    did: String,
228	}
229	
230	/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
231	/// account's authoritative current signing authority and terminate the request accordingly.
232	pub async fn post_authorization_approve(
233	    State(state): State<AppState>,
234	    Json(request): Json<ApprovalRequest>,
235	) -> Result<Json<ApprovalResponse>, ApiError> {
236	    // 1. Cheap syntactic gates before any DB or network work.
237	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
238	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
239	        .ok_or_else(approval_rejected)?;
240	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
241	        return Err(approval_rejected());
242	    }
243	    let approve = match request.decision.as_str() {
244	        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
245	        crypto::OAUTH_CONSENT_DECISION_DENY => false,
246	        _ => return Err(approval_rejected()),
247	    };
248	    let now = crate::time::unix_now_secs();
249	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
250	        return Err(approval_rejected());
251	    }
252	
253	    // 2. Load the pending request; it must be currently approvable.
254	    let pending = get_pending_by_request_id(&state.db, &request.request_id)
255	        .await?
256	        .filter(|p| p.status == "pending" && !p.is_expired)
257	        .ok_or_else(not_approvable)?;
258	
259	    // 3. Account binding: a pre-bound login_hint must match the approving DID; otherwise the wallet
260	    //    binds its own DID here (like the agent claim confirm). Either way the DID must be a local
261	    //    active account so the authorization code can be issued against it.
262	    if let Some(hint) = pending.login_hint.as_deref() {
263	        if hint != request.did {
264	            return Err(approval_rejected());
265	        }
266	    }
267	    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
268	        return Err(approval_rejected());
269	    }
270	
271	    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
272	    //    a denial); the stored set is that, reduced to what was actually requested.
273	    let signed_scope = if approve {
274	        request.granted_scope.as_str()
275	    } else {
276	        ""
277	    };
278	    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);
279	
280	    // 5. Verify the envelope signature, then confirm the signing key is in the account's
281	    //    authoritative current signing authority (never the cached DID doc). Signature first, so an
282	    //    invalid signature never triggers the outbound authority lookup.
283	    let server_did = state.config.resolve_server_did();
284	    let envelope = crypto::encode_oauth_consent_envelope(
285	        &server_did,
286	        &request.did,
287	        &request.signing_key,
288	        &request.request_id,
289	        &pending.client_id,
290	        &request.decision,
291	        signed_scope,
292	        request.timestamp,
293	        &request.nonce,
294	    );
295	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
296	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
297	        .map_err(|_| approval_rejected())?;
298	
299	    let authority = authorized_signing_keys(&state, &request.did)
300	        .await
301	        .map_err(|error| match error {
302	            AuthorityError::Unauthorized(_) => approval_rejected(),
303	            AuthorityError::Lookup(err) => err,
304	        })?;
305	    if !authority.authorizes(&request.signing_key) {
306	        return Err(approval_rejected());
307	    }
308	
309	    // 6. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
310	    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
311	    let mut tx = state.db.begin().await.map_err(|e| {
312	        tracing::error!(error = %e, "failed to begin consent approval transaction");
313	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
314	    })?;
315	    let won = if approve {
316	        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
