        .await
        .map_err(|error| match error {
            AuthorityError::Unauthorized(reason) => {
                tracing::warn!(reason, account_did = %did, "account deletion proof rejected");
                invalid_credentials()
            }
            AuthorityError::Lookup(err) => err,
        })?;
