        async fn token_used(db: &sqlx::SqlitePool, did: &str) -> bool {
            let used_at: Option<String> =
                sqlx::query_scalar("SELECT used_at FROM account_deletion_tokens WHERE did = ?")
                    .bind(did)
                    .fetch_one(db)
                    .await
                    .unwrap();
