26	    onback,
27	    oncomplete,
28	  }: {
29	    did: string;
30	    /** The identity's handle (for context in the warning); may be empty. */
31	    handle?: string;
32	    onback: () => void;
33	    /** Called on success. `wasLast` routes back to onboarding vs. the identity list. */
34	    oncomplete: (wasLast: boolean) => void;
