38	  // forget_confirm is the local-only escape hatch, reachable whenever the server-side
39	  // deletion can't proceed (the account no longer exists on its PDS).
40	  // web_epilogue is the did:web terminal state: the removal succeeded, but the last step
41	  // — taking the DID's document off the domain — belongs to the user, not the wallet.
42	  type Phase =
43	    | 'warn'
44	    | 'requesting'
45	    | 'confirm'
46	    | 'working'
47	    | 'tombstone_retry'
48	    | 'forget_confirm'
49	    | 'web_epilogue';
50	  let phase = $state<Phase>('warn');
51	  let error = $state<string | null>(null);
52	
53	  // A did:web has no PLC tombstone: it is retired by removing its document from the
54	  // domain, which the wallet has no control over. That single fact drives every copy
55	  // branch on this screen — what the warning promises, whether the "also retire on the
56	  // network" advanced option exists at all, and how a removal ends.
57	  let isDidWeb = $derived(did.startsWith('did:web:'));
58	  // The document's authoritative URL, for a concrete instruction rather than a vague one.
59	  // `didWebDocumentUrl` throws on a malformed identifier — fall back to naming no URL
60	  // rather than blocking the epilogue over cosmetics.
61	  let didWebDocUrl = $derived.by(() => {
62	    if (!isDidWeb) return null;
63	    try {
64	      return didWebDocumentUrl(did);
65	    } catch {
66	      return null;
67	    }
68	  });
69	
70	  // Carried from the successful removal into `web_epilogue`, so the Done button routes
71	  // exactly where an immediate `oncomplete` would have.
72	  let epilogueWasLast = $state(false);
73	
74	  let code = $state('');
75	  let password = $state('');
76	
77	  let canConfirm = $derived(code.trim().length > 0 && password.length > 0);
78	
79	  // If a prior attempt already deleted the PDS account but was interrupted before the
80	  // tombstone + wipe finished (the app was killed mid-flow), the account is gone and the
81	  // single-use email code is spent — the request flow would fail. Resume straight to the
82	  // tombstone-only retry instead. Checked on every mount so this self-corrects no matter
83	  // how the screen was reached (launch reconciliation or manual navigation).
84	  onMount(async () => {
85	    try {
86	      const pending = await listPendingRemovals();
87	      if (pending.includes(did) && phase === 'warn') {
88	        phase = 'tombstone_retry';
89	      }
90	    } catch (e) {
91	      console.warn('listPendingRemovals failed:', e);
92	    }
93	  });
94	
95	  // Hold-to-remove: a deliberate, irreversible confirmation gesture (matches the
96	  // recovery-override screen), gated by biometrics before anything is sent.
97	  const HOLD_MS = 1500;
98	  const hold = useHoldGesture({
99	    durationMs: HOLD_MS,
100	    oncomplete: () => {
101	      hold.state.progress = 1;
102	      confirm();
103	    },
104	    canStart: () => phase === 'confirm' && canConfirm,
105	  });
106	  let holdFill = $derived(hold.state.progress);
107	
108	  // A separate hold gesture for the "forget" confirmation, so its own progress and canStart
109	  // guard stay independent of the delete-and-tombstone hold above.
110	  const forgetHold = useHoldGesture({
111	    durationMs: HOLD_MS,
112	    oncomplete: () => {
113	      forgetHold.state.progress = 1;
114	      confirmForget();
115	    },
116	    canStart: () => phase === 'forget_confirm',
117	  });
118	  let forgetHoldFill = $derived(forgetHold.state.progress);
119	
120	  // Advanced escape-hatch options, revealed behind a disclosure. `alsoTombstone` upgrades the
121	  // local-only wipe into a full network retirement (sign + publish a did:plc tombstone) for an
122	  // advanced user who is certain they want to torch the identity everywhere, not just here.
123	  // Offered for a did:plc only: there is no did:web tombstone to publish, so the option would
124	  // promise a network-wide retirement the wallet cannot perform.
125	  let showAdvanced = $state(false);
126	  let alsoTombstone = $state(false);
127	
128	  // The message shown during the `working` step — set by each path so it tells the literal truth
129	  // (a local-only forget must not claim it is "deleting your account").
130	  let workingMessage = $state('Removing identity…');

130	  let workingMessage = $state('Removing identity…');
131	
132	  /** Enter the escape hatch from any stuck state, resetting its advanced options. */
133	  function startForget() {
134	    error = null;
135	    showAdvanced = false;
136	    alsoTombstone = false;
137	    phase = 'forget_confirm';
138	  }
139	
140	  /** Translate a typed RemovalError (or any throwable) into a display string. */
141	  function messageFor(raw: unknown): string | null {
142	    // A dismissed unlock prompt is the user's decision, not a failure: say nothing.
143	    if (isUnlockCancelled(raw)) return null;
144	    if (isCodedError(raw)) {
145	      const err = raw as RemovalError;
146	      switch (err.code) {
147	        case 'SESSION_REQUIRED':
148	          return 'This identity needs to be unlocked first.';
149	        case 'REQUEST_DELETE_FAILED':
150	          return `Could not start deletion: ${err.message || 'unknown error'}`;
151	        case 'INVALID_TOKEN':
152	          return 'That password or confirmation code was not accepted. Check your email and try again.';
153	        case 'ACCOUNT_DELETE_FAILED':
154	          return `Account deletion failed: ${err.message || 'unknown error'}`;
155	        case 'INVALID_AUDIT_LOG':
156	          return `Could not read the identity's PLC log: ${err.message || 'unknown error'}`;
157	        case 'TOMBSTONE_SIGNING_FAILED':
158	          return `Could not sign the tombstone: ${err.message || 'unknown error'}`;
159	        case 'PLC_DIRECTORY_ERROR':
160	          return `The PLC directory rejected the tombstone: ${err.message || 'unknown error'}`;
161	        case 'IDENTITY_NOT_FOUND':
162	          return `Identity not found: ${err.message || 'unknown error'}`;
163	        case 'LOCAL_WIPE_FAILED':
164	          return `The account was removed, but local cleanup failed: ${err.message || 'unknown error'}`;
165	        case 'RATE_LIMITED':
166	          return 'Rate limited by the server. Please wait a moment and try again.';
167	        case 'NETWORK_ERROR':
168	          return `Network error: ${err.message || 'unknown error'}`;
169	        default:
170	          return (err as { message?: string }).message || 'An unexpected error occurred.';
171	      }
172	    }
173	    return 'An unexpected error occurred. Please try again.';
174	  }
175	
176	  /** Step 1: ask the PDS to email a confirmation code (unlocking the session if needed). */
177	  async function startRequest() {
178	    phase = 'requesting';
179	    error = null;
180	    try {
181	      await requestIdentityRemoval(did);
182	      phase = 'confirm';
183	    } catch (raw: unknown) {
184	      // A locked identity: run the host's unlock (biometric sovereign login on Custos, a
185	      // password prompt on any other host) once, then retry.
186	      if (isCodedError(raw) && (raw as RemovalError).code === 'SESSION_REQUIRED') {
187	        try {
188	          await unlockIdentity(did);
189	          await requestIdentityRemoval(did);
190	          phase = 'confirm';
191	          return;
192	        } catch (retryRaw: unknown) {
193	          console.error('Unlock-then-request failed:', retryRaw);
194	          error = messageFor(retryRaw);
195	          phase = 'warn';
196	          return;
197	        }
198	      }
199	      console.error('requestIdentityRemoval failed:', raw);
200	      error = messageFor(raw);
201	      phase = 'warn';
202	    }
203	  }
204	
205	  /** Step 2: delete on the PDS, tombstone the DID, wipe locally. Biometric-gated. */
206	  async function confirm() {
207	    error = null;
208	    try {
209	      await authenticateBiometric('Confirm permanent removal of this identity');
210	    } catch {
211	      hold.state.progress = 0;
212	      return; // gate declined — nothing sent.
213	    }
214	
215	    workingMessage = isDidWeb
216	      ? 'Deleting your account and removing this identity…'
217	      : 'Deleting your account and retiring the identity…';
218	    phase = 'working';
219	    try {
220	      const outcome: RemovalOutcome = await confirmIdentityRemoval(did, password, code.trim());
221	      finishRemoval(outcome);
222	    } catch (raw: unknown) {
223	      console.error('confirmIdentityRemoval failed:', raw);
224	      hold.state.progress = 0;
