239	   *
240	   * A tombstone-less outcome (`tombstoneCid: null` — a did:web) is NOT finished from the
241	   * user's point of view: the DID keeps resolving until its document leaves the domain, so
242	   * the screen says so instead of silently returning to the identity list as if the
243	   * identity had been retired network-wide.
244	   */
245	  function finishRemoval(outcome: RemovalOutcome) {
246	    if (outcome.tombstoneCid === null) {
